            parts = listOf(
                StoryPart(1, "Too Many Papers", listOf("At the community centre, Bisi noticed that the public noticeboard was crowded with old flyers, overlapping announcements, and handwritten corrections.", "The centre coordinator said some notices were useful, but visitors could not tell which were current.", "Bisi offered to help organise a supervised review.")),
                StoryPart(2, "A Simple Audit", listOf("The youth team listed the types of notices without copying personal contact details.", "They found event announcements, public-service information, class schedules, and several expired posters.", "The coordinator explained that only authorised staff could approve official notices.")),
                StoryPart(3, "Dates and Sources", listOf("The team proposed adding a date, source, and expiry date to each new notice.", "The coordinator agreed and asked them to draft a template for review.", "Students learned that a clear layout could not replace checking whether information was accurate.")),
                StoryPart(4, "The Urgent Flyer", listOf("A flyer about a public meeting had no date and included an unclear venue.", "Rather than guessing, the team contacted the issuing organisation through its published office channel.", "The organisation supplied a corrected notice, which staff approved before display.")),
                StoryPart(5, "Making Space", listOf("The team grouped notices by topic and created a clear section for current community events.", "They used large headings and left space around each item so readers could scan the board easily.", "The centre checked that the arrangement did not cover safety information or building directions.")),
                StoryPart(6, "A Privacy Concern", listOf("One old flyer included a personal phone number that the person had not intended to publish permanently.", "The coordinator removed it and contacted the contributor to explain the change.", "The team added a privacy check to the notice approval process.")),
