                StoryPart(8, "The Digital Copy", listOf("The centre considered sharing the noticeboard online. Staff reviewed what could be published and which contact details should remain private.", "The youth team prepared a digital layout using only approved notices and public contact channels.", "They included a reminder that online copies could become outdated and should be checked against the centre's current board.")),
                StoryPart(9, "A Month Later", listOf("The team reviewed the board after a month and removed expired notices with staff approval.", "Visitors said it was easier to find class times and event details.", "The coordinator scheduled a monthly review and thanked the students for creating a process that could continue.")),
                StoryPart(10, "Information People Can Use", listOf("The noticeboard became clearer because every item had an owner, a date, and a review process.", "Bisi wrote a short guide for future volunteers explaining how to organise notices without changing official information or exposing private details.", "She learned that communication was not simply putting words where people could see them. It was making sure the right words reached people at the right time."))
